const D = { polish: .6, scale: 1, energy: .6, density: .5, hue: 44, speed: 1, x: .5, y: .4, alpha: 1, style: 'calacatta', act: 'dolly', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2rgb=(h,s,b)=>{ h=md(h,360)/60; s=cl(s,0,100)/100; b=cl(b,0,100)/100;
  const c=b*s, x=c*(1-Math.abs((h%2)-1)), m=b-c; let r,g,l;
  if(h<1){r=c;g=x;l=0;} else if(h<2){r=x;g=c;l=0;} else if(h<3){r=0;g=c;l=x;}
  else if(h<4){r=0;g=x;l=c;} else if(h<5){r=x;g=0;l=c;} else {r=c;g=0;l=x;}
  return [(r+m)*255,(g+m)*255,(l+m)*255]; };
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const sty=P.style, act=P.act;
const pol=cl(P.polish,0,1), sc=cl(P.scale,.4,2.4), al=cl(P.alpha,0,1);
const dens=cl(P.density,0,1), spd=cl(P.speed,.1,4), en=cl(P.energy,0,1);
const H=md(P.hue,360), T=K.t*spd;
const TD=K.t*(.45+.55*Math.min(spd,3));

S.bass=(S.bass||0)*.86+(A.bass||0)*.14;
S.tre=(S.tre||0)*.86+(A.treble||0)*.14;

// ---- seeded wrapping fBm field (once per seed) ----
const NZ=160;
if(S.nzK!==P.seed || !S.nz){ S.nzK=P.seed; const F=new Float32Array(NZ*NZ); let amp=1, tot=0;
  for(let o=0;o<4;o++){ const per=4<<o, cell=NZ/per;
    const lv=new Float32Array(per*per);
    for(let k=0;k<per*per;k++) lv[k]=fr(o*977.3+k*1.317+3.7);
    for(let j=0;j<NZ;j++){ const gy=j/cell, jy=Math.floor(gy), fy=gy-jy, vv=fy*fy*(3-2*fy);
      const j0=(jy%per)*per, j1=((jy+1)%per)*per;
      for(let i=0;i<NZ;i++){ const gx=i/cell, ix=Math.floor(gx), fx=gx-ix, uu=fx*fx*(3-2*fx);
        const i0=ix%per, i1=(ix+1)%per;
        const a=lv[j0+i0], b=lv[j0+i1], c=lv[j1+i0], d=lv[j1+i1];
        F[j*NZ+i]+=amp*(a+(b-a)*uu+(c-a)*vv+(a-b-c+d)*uu*vv); } }
    tot+=amp; amp*=0.52; }
  for(let k=0;k<NZ*NZ;k++) F[k]=F[k]/tot;
  S.nz=F; }
const NF=S.nz, CEL=NZ/4;
const nzAt=(x,y)=>{ x*=CEL; y*=CEL;
  let xi=Math.floor(x), yi=Math.floor(y); const fx=x-xi, fy=y-yi;
  xi=md(xi,NZ); yi=md(yi,NZ); const x1=(xi+1)%NZ, y1=(yi+1)%NZ, r0=yi*NZ, r1=y1*NZ;
  const a=NF[r0+xi], b=NF[r0+x1], c=NF[r1+xi], d=NF[r1+x1];
  return a+(b-a)*fx+(c-a)*fy+(a-b-c+d)*fx*fy; };

const BW=200, BH=cl(Math.round(BW*Hh/Math.max(1,W)),60,200);
if(!S.g || S.gk!==BW+'x'+BH){ if(S.g&&S.g.remove)S.g.remove();
  S.g=createGraphics(BW,BH); S.gk=BW+'x'+BH; }
const G=S.g;

// ---- dramaturgy ----
const sec=((K.section|0)%8+8)%8;
let dolly, lightRate, wearF;
if(act==='sweep'){ dolly=.22; lightRate=2.3; wearF=1; }
else if(act==='wear'){ dolly=.6; lightRate=.8; wearF=.4+1.5*(.5+.5*Math.sin(sec*.85+T*.018)); }
else { dolly=1; lightRate=1; wearF=1; }

// ---- the camera dollies along the floor and the light walks the polish. Both monotonic:
// neither can re-phase away over an 8s window.
const scroll=.185*TD*dolly;
const lAz=cl(P.x,0,1)*TAU + .0155*TD*lightRate + .24*Math.sin(TD*.045*lightRate) + .12*Math.sin(TD*.103*lightRate+1.4);
// the hall lights standing above the floor — a polished plane smears each one toward you
const NLM=3;
const lampX=[], lampA=[];
for(let k=0;k<NLM;k++){
  lampX.push((fr(k*5.7+400)-.5)*2.2 + .34*Math.sin(lAz*(.7+.22*k)+k*2.3));
  lampA.push(.5+.5*fr(k*5.7+401));
}

// ---- style ----
let STONE, VEIN, VEIN2, JOINT, LAMP, radio=0;
if(sty==='nero'){ STONE=hsb2rgb(H+186,16,11); VEIN=hsb2rgb(H+10,4,92); VEIN2=hsb2rgb(H+16,10,62); JOINT=hsb2rgb(H+186,20,5); LAMP=[255,252,244]; }
else if(sty==='breccia'){ STONE=hsb2rgb(H-6,30,44); VEIN=hsb2rgb(H+6,10,86); VEIN2=hsb2rgb(H-14,44,26); JOINT=hsb2rgb(H-10,34,15); LAMP=[255,244,220]; }
else if(sty==='serpentine'){ STONE=hsb2rgb(H+104,44,22); VEIN=hsb2rgb(H+96,8,88); VEIN2=hsb2rgb(H+110,32,44); JOINT=hsb2rgb(H+104,40,9); LAMP=[236,255,242]; }
else if(sty==='radiograph'){ STONE=hsb2rgb(H+184,10,16); VEIN=hsb2rgb(H+180,4,98); VEIN2=hsb2rgb(H+180,6,60); JOINT=hsb2rgb(H+184,12,7); LAMP=[220,244,255]; radio=1; }
else { STONE=hsb2rgb(H+16,7,72); VEIN=hsb2rgb(H+192,12,34); VEIN2=hsb2rgb(H-6,34,58); JOINT=hsb2rgb(H+8,12,40); LAMP=[255,250,238]; }

// ---- the plane ----
const hz=cl(P.y,.20,.74)*Hh, gH=Math.max(24,Hh-hz);
const vpx=cl(P.x,.05,.95)*W;
const tileW=.62*sc;
const veinF=(1.5+dens*2.2);
const glow=(.35+.95*en)*(.55+.7*K.intensity)+S.tre*.3*en;
const brecc=(sty==='breccia');

G.loadPixels();
const px=G.pixels;
for(let j=0;j<BH;j++){
  const sy=(j/BH)*Hh;
  const o0=j*BW*4;
  if(sy<=hz+.5){ for(let i=0;i<BW;i++) px[o0+i*4+3]=0; continue; }
  const t=cl((sy-hz)/gH,0.0001,1);
  const persp=1/(t*t*1.55+.105);
  const lodMix=cl(1.25/(1+persp*.42),0,1);     // the stone loses its grain as it recedes
  const rowW=(W*.5)/(persp*.30+.30);
  const wz=persp*.90+scroll;
  const fade=cl(1-Math.pow(1-t,2.4)*1.05,0,1);
  for(let i=0;i<BW;i++){
    const sx=(i/BW)*W;
    const wx=((sx-vpx)/Math.max(1e-4,rowW))*2.6/sc;
    const o=o0+i*4;
    // which slab is this, and where in it?
    const tu=wx/tileW, tv=wz/tileW;
    const ti=Math.floor(tu), tj=Math.floor(tv);
    let fu=tu-ti; const fv=tv-tj;
    // book-matching: alternate slabs are cut from the same block and mirrored
    if(md(ti+tj,2)<1) fu=1-fu;
    const hsh=fr(ti*13.1+tj*7.7+500)*23.7, hsh2=fr(ti*13.1+tj*7.7+501)*17.3;
    // veining: a domain-warped ridge field, unique per slab
    const gx2=hsh+fu*veinF, gy2=hsh2+fv*veinF;
    const wq=(nzAt(gx2*.9+3.1, gy2*.9+8.8)-.5)*1.25;
    const v1=nzAt(gx2*1.5+wq*1.6+1.1, gy2*1.5+wq*1.1+5.5);
    const v2=nzAt(gx2*4.1+wq*2.2-2.2, gy2*4.1-wq*1.4+9.9);
    let rid=1-Math.abs(v1-.5)*2.9;
    let rid2=1-Math.abs(v2-.5)*3.4;
    rid=cl(rid,0,1); rid2=cl(rid2,0,1);
    let vn=Math.pow(rid,2.4)*(.55+.5*dens);
    let vn2=Math.pow(rid2,3.2)*(.35+.4*dens);
    vn*=lodMix; vn2*=lodMix*lodMix;
    let R,Gc,B;
    if(brecc){
      // breccia: the block was shattered and healed, so it is clasts in a matrix
      const cshard=cl((nzAt(gx2*2.6+11.1, gy2*2.6+4.4)-.42)*3.2,0,1);
      const mtx=cl(1-cshard,0,1)*lodMix;
      R=STONE[0]+(VEIN2[0]-STONE[0])*mtx; Gc=STONE[1]+(VEIN2[1]-STONE[1])*mtx; B=STONE[2]+(VEIN2[2]-STONE[2])*mtx;
      R=R+(VEIN[0]-R)*vn2*.9; Gc=Gc+(VEIN[1]-Gc)*vn2*.9; B=B+(VEIN[2]-B)*vn2*.9;
    } else {
      R=STONE[0]+(VEIN2[0]-STONE[0])*vn2; Gc=STONE[1]+(VEIN2[1]-STONE[1])*vn2; B=STONE[2]+(VEIN2[2]-STONE[2])*vn2;
      R=R+(VEIN[0]-R)*vn; Gc=Gc+(VEIN[1]-Gc)*vn; B=B+(VEIN[2]-B)*vn;
    }
    // the joint between slabs, and the chipping along its edge
    const ju=Math.min(fu,1-fu), jv=Math.min(fv,1-fv);
    const jw=.020+.016*dens;
    const chipn=(nzAt(gx2*9+31.1, gy2*9+17.7)-.5)*.014;
    const joint=cl(1-(Math.min(ju,jv)-chipn)/jw,0,1)*lodMix;
    R=R+(JOINT[0]-R)*joint*.92; Gc=Gc+(JOINT[1]-Gc)*joint*.92; B=B+(JOINT[2]-B)*joint*.92;
    // traffic: the polish is walked off down the middle of the hall
    const wearN=nzAt(wx*.42+41.1, wz*.20+3.3);
    const path=Math.exp(-Math.pow(wx/(.62*sc),2))*(.35+.5*wearN)*wearF;
    const polish=cl(pol*(1-path*.55),0,1);
    // polishing deepens the stone itself — a honed slab reads chalky and pale beside it
    const deep=1-polish*.30;
    R*=deep; Gc*=deep; B*=deep;
    // a polished plane smears each lamp toward the viewer: long, narrow, never a blob
    let st=0;
    for(let k=0;k<NLM;k++){
      const wid=(.05+.34*(1-t))*sc*(1+(1-polish)*3.2);
      const d=(wx-lampX[k])/wid;
      st+=lampA[k]*Math.exp(-d*d)*(.28+.95*t);
    }
    const rip=1+.30*(nzAt(wx*1.7+7.7, wz*.5+2.2)-.5)*(1-polish*.6);
    const sp=cl(st*Math.pow(polish,.75)*1.5*glow*rip*(.3+.9*fade)*(1-joint*.7),0,3.0)*(radio?38:74);
    R+=LAMP[0]*sp/255; Gc+=LAMP[1]*sp/255; B+=LAMP[2]*sp/255;
    if(radio){
      // non-representational: a radiographic plate — mineral density only, no stone, no room
      const dsy=cl(vn*1.5+vn2*.9+joint*.5,0,1);
      const v=.10+.90*Math.pow(dsy,.7)*fade;
      R=STONE[0]*(1-v)+VEIN[0]*v; Gc=STONE[1]*(1-v)+VEIN[1]*v; B=STONE[2]*(1-v)+VEIN[2]*v;
      R+=LAMP[0]*sp*.35/255; Gc+=LAMP[1]*sp*.35/255; B+=LAMP[2]*sp*.35/255;
    }
    // haze the far floor into the horizon so the plane really recedes
    const hf=1-fade;
    R=R*(1-hf*.70)+STONE[0]*hf*.70*.85; Gc=Gc*(1-hf*.70)+STONE[1]*hf*.70*.85; B=B*(1-hf*.70)+STONE[2]*hf*.70*.9;
    px[o]=R<0?0:R>255?255:R; px[o+1]=Gc<0?0:Gc>255?255:Gc; px[o+2]=B<0?0:B>255?255:B; px[o+3]=255;
  }
}
G.updatePixels();

noStroke();
if(al<1){ push(); drawingContext.globalAlpha=al; image(G,0,0,W,Hh); pop(); }
else image(G,0,0,W,Hh);
const dc=drawingContext;
blendMode(BLEND); dc.globalAlpha=1; dc.shadowBlur=0; noStroke(); noTint();
